// Hand-added regression test for the OAuth scope fix (GH servosity/msp-skills#7).
// NOT generated by the Printing Press; guards that config.Load applies the
// documented default scope ("all") and honors an explicit HALOPSA_SCOPE override.

package config

import (
	"path/filepath"
	"testing"
)

// HaloPSA's client_credentials grant requires an explicit scope; a token minted
// without one is rejected with HTTP 401 on every API call. The CLI documents a
// default of "all", so Load must materialize it when nothing is configured.
func TestLoadDefaultsScopeToAll(t *testing.T) {
	// Point at a non-existent config file and clear the scope env so Load falls
	// through to its default. t.Setenv also isolates from the ambient env.
	t.Setenv("HALOPSA_CONFIG", filepath.Join(t.TempDir(), "absent.toml"))
	t.Setenv("HALOPSA_SCOPE", "")

	cfg, err := Load("")
	if err != nil {
		t.Fatalf("Load: %v", err)
	}
	if cfg.HalopsaScope != "all" {
		t.Fatalf("HalopsaScope = %q, want %q (documented default)", cfg.HalopsaScope, "all")
	}
	// A defaulted scope must not masquerade as a configured credential source.
	if cfg.AuthSource == "config" {
		t.Fatalf("AuthSource = %q; defaulted scope must not set auth_source", cfg.AuthSource)
	}
}

func TestLoadHonorsScopeOverride(t *testing.T) {
	t.Setenv("HALOPSA_CONFIG", filepath.Join(t.TempDir(), "absent.toml"))
	t.Setenv("HALOPSA_SCOPE", "read:tickets")

	cfg, err := Load("")
	if err != nil {
		t.Fatalf("Load: %v", err)
	}
	if cfg.HalopsaScope != "read:tickets" {
		t.Fatalf("HalopsaScope = %q, want %q", cfg.HalopsaScope, "read:tickets")
	}
}
